using CounterpartyRisk.Domain.Contracts.Results;

namespace CounterpartyRisk.Domain.Contracts.Quality;

/// <summary>How a figure relates to its source (BCBS 239 lineage).</summary>
public enum LineageStatus
{
    /// <summary>Taken as published by the source.</summary>
    Real = 1,

    /// <summary>Derived from a real source (conversion, cross rate, mapping).</summary>
    Transformed = 2,

    /// <summary>Generated by the synthetic portfolio, never presented as real.</summary>
    Synthetic = 3,
}

/// <summary>Lineage of a dataset: source identifier and the attribution the licence requires.</summary>
/// <param name="Status">Real, transformed or synthetic.</param>
/// <param name="SourceId">Stable source code, e.g. <c>ecb-exr</c> or <c>gleif-golden-copy</c>.</param>
/// <param name="Attribution">Text to display, e.g. "Source: ECB statistics.".</param>
public sealed record DataLineage(LineageStatus Status, string SourceId, string Attribution)
{
    public static Result<DataLineage> Create(LineageStatus status, string? sourceId, string? attribution)
    {
        if (!Enum.IsDefined(status))
        {
            return Error.Validation("lineage.invalid_status", "Unknown lineage status.");
        }

        if (string.IsNullOrWhiteSpace(sourceId) || sourceId.Length > 64
            || !sourceId.All(c => char.IsAsciiLetterLower(c) || char.IsAsciiDigit(c) || c is '-' or '.'))
        {
            return Error.Validation("lineage.invalid_source", "A source id is 1 to 64 lower-case letters, digits, '-' or '.'.");
        }

        if (string.IsNullOrWhiteSpace(attribution) || attribution.Length > 256)
        {
            return Error.Validation("lineage.invalid_attribution", "An attribution is 1 to 256 characters.");
        }

        return new DataLineage(status, sourceId, attribution);
    }
}

public enum CompletenessStatus
{
    Complete = 1,

    Partial = 2,

    Missing = 3,
}

/// <summary>BCBS 239 completeness of a dataset, from data quality checks (#19).</summary>
public sealed record DataCompleteness
{
    private DataCompleteness(CompletenessStatus status, decimal percent)
    {
        Status = status;
        Percent = percent;
    }

    public CompletenessStatus Status { get; }

    /// <summary>Share of expected records present, between 0 and 100.</summary>
    public decimal Percent { get; }

    public static Result<DataCompleteness> FromPercent(decimal percent) => percent switch
    {
        < 0m or > 100m => Error.Validation("completeness.out_of_range", "Completeness is between 0 and 100 %."),
        100m => new DataCompleteness(CompletenessStatus.Complete, percent),
        0m => new DataCompleteness(CompletenessStatus.Missing, percent),
        _ => new DataCompleteness(CompletenessStatus.Partial, percent),
    };
}
